import pytest
from rich.traceback import Traceback
from rich.console import Console
from io import StringIO

def test_exception_notes():
    console = Console(file=StringIO(), force_terminal=True)

    try:
        try:
            raise ValueError("Main Error")
        except ValueError as e:
            e.__notes__ = "Note 1\nNote 2"
            raise
    except ValueError:
        tb = Traceback.from_exception(console)
        console.print(tb)

    output = console.file.getvalue()
    assert "Note: Note 1\nNote 2" in output

def test_exception_notes_list():
    console = Console(file=StringIO(), force_terminal=True)

    try:
        try:
            raise ValueError("Main Error")
        except ValueError as e:
            # Python 3.11+ supports __notes__ as a string. 
            # However, the fix handles lists just in case or as a result of some logic.
            e.__notes__ = ["Note A", "Note B"]
            raise
    except ValueError:
        tb = Traceback.from_exception(console)
        console.print(tb)

    output = console.file.getvalue()
    assert "Note A" in output
    assert "Note B" in output

def test_no_notes():
    console = Console(file=StringIO(), force_terminal=True)

    try:
        raise ValueError("Main Error")
    except ValueError:
        tb = Traceback.from_exception(console)
        console.print(tb)

    output = console.file.getvalue()
    assert "Note:" not in output

